-- Aprenda se Divertindo · 98 · Simulado 2 da Trilha Policial
-- Rode depois do 97-simulado-fim-de-semana.sql. Cole tudo no SQL Editor e clique em Run.
-- Cria e publica o Simulado 2 da trilha Policial: abre no sábado, 31/10/2026, às 0h, e fecha no domingo, 01/11/2026, às 23h59.
-- 100 questões de A a E, estilo AOCP, nível mais difícil e com casos práticos, 4 horas de prova.
-- Conhecimentos gerais (40): Português 10, Raciocínio Lógico 7, Informática 7, Atualidades 4, Igualdade Racial e de Gênero 4,
--   Medicina Legal 4, Legislação Geral 4. Específicos (60): Penal 10, Processo Penal 9, Legislação Extravagante 9,
--   Contabilidade 8, Constitucional 8, Administrativo 8, Estatística 8.
-- Gabarito equilibrado: 20 questões com cada letra (A a E). Gabarito comentado liberado na segunda, 02/11, às 0h.
-- Rodar de novo atualiza as questões, desde que ninguém tenha começado a prova.

do $$
declare sid bigint; lista jsonb := $q$[{"materia": "port", "texto_base": "Durante muito tempo, acreditou-se que a principal arma contra o crime fosse a presença ostensiva do Estado nas ruas. Embora essa presença continue necessária, ela já não basta. Hoje, boa parte dos golpes começa longe das calçadas: numa mensagem que imita o banco, num perfil falso que oferece emprego, num link que promete prêmio. A vítima, que raramente vê o rosto de quem a engana, só percebe o prejuízo quando o dinheiro já atravessou várias contas.\n\nDiante desse cenário, investigar exige mais do que coragem. Exige paciência para seguir rastros digitais, cooperação com instituições financeiras e, sobretudo, rapidez — porque, nesse tipo de crime, cada hora perdida diminui as chances de recuperar os valores. Não se trata, porém, de substituir o trabalho de campo pela tela do computador. Os dados indicam caminhos; são as pessoas que os percorrem, confirmam ou descartam.", "enunciado": "De acordo com o texto, é correto afirmar que", "opcoes": ["a coragem do investigador é dispensável nos crimes cometidos pela internet.", "a apuração dos golpes digitais combina análise de dados e trabalho de campo.", "a tela do computador substitui com vantagem o trabalho de campo.", "a vítima costuma perceber o golpe antes de o dinheiro ser transferido.", "a presença ostensiva do Estado nas ruas deixou de ser necessária."], "gabarito": 1, "explicacao": "O último parágrafo diz que não se trata de substituir o trabalho de campo pela tela: os dados indicam caminhos e as pessoas os percorrem. O texto afirma que a presença nas ruas 'continua necessária' e que investigar exige 'mais do que coragem' (não que ela seja dispensável)."}, {"materia": "port", "texto_base": "Durante muito tempo, acreditou-se que a principal arma contra o crime fosse a presença ostensiva do Estado nas ruas. Embora essa presença continue necessária, ela já não basta. Hoje, boa parte dos golpes começa longe das calçadas: numa mensagem que imita o banco, num perfil falso que oferece emprego, num link que promete prêmio. A vítima, que raramente vê o rosto de quem a engana, só percebe o prejuízo quando o dinheiro já atravessou várias contas.\n\nDiante desse cenário, investigar exige mais do que coragem. Exige paciência para seguir rastros digitais, cooperação com instituições financeiras e, sobretudo, rapidez — porque, nesse tipo de crime, cada hora perdida diminui as chances de recuperar os valores. Não se trata, porém, de substituir o trabalho de campo pela tela do computador. Os dados indicam caminhos; são as pessoas que os percorrem, confirmam ou descartam.", "enunciado": "Sem prejuízo do sentido e da correção, o trecho “Embora essa presença continue necessária” poderia ser reescrito como", "opcoes": ["Porque essa presença continua necessária", "À medida que essa presença continua necessária", "Contanto que essa presença continue necessária", "Desde que essa presença continue necessária", "Ainda que essa presença continue necessária"], "gabarito": 4, "explicacao": "'Embora' é conjunção concessiva, assim como 'ainda que'. 'Porque' é causal, 'desde que' e 'contanto que' são condicionais e 'à medida que' é proporcional."}, {"materia": "port", "texto_base": "Durante muito tempo, acreditou-se que a principal arma contra o crime fosse a presença ostensiva do Estado nas ruas. Embora essa presença continue necessária, ela já não basta. Hoje, boa parte dos golpes começa longe das calçadas: numa mensagem que imita o banco, num perfil falso que oferece emprego, num link que promete prêmio. A vítima, que raramente vê o rosto de quem a engana, só percebe o prejuízo quando o dinheiro já atravessou várias contas.\n\nDiante desse cenário, investigar exige mais do que coragem. Exige paciência para seguir rastros digitais, cooperação com instituições financeiras e, sobretudo, rapidez — porque, nesse tipo de crime, cada hora perdida diminui as chances de recuperar os valores. Não se trata, porém, de substituir o trabalho de campo pela tela do computador. Os dados indicam caminhos; são as pessoas que os percorrem, confirmam ou descartam.", "enunciado": "No trecho “são as pessoas que os percorrem, confirmam ou descartam”, o pronome “os” retoma", "opcoes": ["caminhos.", "valores.", "rastros digitais.", "dados.", "golpes."], "gabarito": 0, "explicacao": "Quem é percorrido, confirmado ou descartado são os caminhos indicados pelos dados: 'Os dados indicam caminhos; são as pessoas que os percorrem'."}, {"materia": "port", "texto_base": "Durante muito tempo, acreditou-se que a principal arma contra o crime fosse a presença ostensiva do Estado nas ruas. Embora essa presença continue necessária, ela já não basta. Hoje, boa parte dos golpes começa longe das calçadas: numa mensagem que imita o banco, num perfil falso que oferece emprego, num link que promete prêmio. A vítima, que raramente vê o rosto de quem a engana, só percebe o prejuízo quando o dinheiro já atravessou várias contas.\n\nDiante desse cenário, investigar exige mais do que coragem. Exige paciência para seguir rastros digitais, cooperação com instituições financeiras e, sobretudo, rapidez — porque, nesse tipo de crime, cada hora perdida diminui as chances de recuperar os valores. Não se trata, porém, de substituir o trabalho de campo pela tela do computador. Os dados indicam caminhos; são as pessoas que os percorrem, confirmam ou descartam.", "enunciado": "No segundo parágrafo, o travessão empregado antes de “porque, nesse tipo de crime...” introduz", "opcoes": ["uma justificativa para a importância da rapidez.", "uma conclusão sobre o trabalho de campo.", "uma enumeração de exemplos de golpes digitais.", "uma citação da fala de um investigador.", "uma ressalva que contradiz a ideia anterior."], "gabarito": 0, "explicacao": "O trecho após o travessão explica por que a rapidez é necessária: cada hora perdida diminui as chances de recuperar os valores. É uma justificativa (causa)."}, {"materia": "port", "texto_base": "Durante muito tempo, acreditou-se que a principal arma contra o crime fosse a presença ostensiva do Estado nas ruas. Embora essa presença continue necessária, ela já não basta. Hoje, boa parte dos golpes começa longe das calçadas: numa mensagem que imita o banco, num perfil falso que oferece emprego, num link que promete prêmio. A vítima, que raramente vê o rosto de quem a engana, só percebe o prejuízo quando o dinheiro já atravessou várias contas.\n\nDiante desse cenário, investigar exige mais do que coragem. Exige paciência para seguir rastros digitais, cooperação com instituições financeiras e, sobretudo, rapidez — porque, nesse tipo de crime, cada hora perdida diminui as chances de recuperar os valores. Não se trata, porém, de substituir o trabalho de campo pela tela do computador. Os dados indicam caminhos; são as pessoas que os percorrem, confirmam ou descartam.", "enunciado": "Em “Não se trata, porém, de substituir o trabalho de campo”, o termo “se” classifica-se como", "opcoes": ["pronome reflexivo, com sentido recíproco.", "conjunção subordinativa condicional.", "parte integrante do verbo pronominal.", "índice de indeterminação do sujeito.", "partícula apassivadora, com sujeito paciente."], "gabarito": 3, "explicacao": "'Tratar-se de' é verbo transitivo indireto com 'se' índice de indeterminação do sujeito: o verbo fica no singular e não há sujeito identificável."}, {"materia": "port", "texto_base": "Durante muito tempo, acreditou-se que a principal arma contra o crime fosse a presença ostensiva do Estado nas ruas. Embora essa presença continue necessária, ela já não basta. Hoje, boa parte dos golpes começa longe das calçadas: numa mensagem que imita o banco, num perfil falso que oferece emprego, num link que promete prêmio. A vítima, que raramente vê o rosto de quem a engana, só percebe o prejuízo quando o dinheiro já atravessou várias contas.\n\nDiante desse cenário, investigar exige mais do que coragem. Exige paciência para seguir rastros digitais, cooperação com instituições financeiras e, sobretudo, rapidez — porque, nesse tipo de crime, cada hora perdida diminui as chances de recuperar os valores. Não se trata, porém, de substituir o trabalho de campo pela tela do computador. Os dados indicam caminhos; são as pessoas que os percorrem, confirmam ou descartam.", "enunciado": "O vocábulo “sobretudo”, no segundo parágrafo, pode ser substituído, sem alteração de sentido, por", "opcoes": ["por conseguinte.", "entretanto.", "principalmente.", "em contrapartida.", "ou seja."], "gabarito": 2, "explicacao": "'Sobretudo' é advérbio que destaca um elemento entre os demais, como 'principalmente' ou 'acima de tudo'."}, {"materia": "port", "texto_base": "Durante muito tempo, acreditou-se que a principal arma contra o crime fosse a presença ostensiva do Estado nas ruas. Embora essa presença continue necessária, ela já não basta. Hoje, boa parte dos golpes começa longe das calçadas: numa mensagem que imita o banco, num perfil falso que oferece emprego, num link que promete prêmio. A vítima, que raramente vê o rosto de quem a engana, só percebe o prejuízo quando o dinheiro já atravessou várias contas.\n\nDiante desse cenário, investigar exige mais do que coragem. Exige paciência para seguir rastros digitais, cooperação com instituições financeiras e, sobretudo, rapidez — porque, nesse tipo de crime, cada hora perdida diminui as chances de recuperar os valores. Não se trata, porém, de substituir o trabalho de campo pela tela do computador. Os dados indicam caminhos; são as pessoas que os percorrem, confirmam ou descartam.", "enunciado": "Mantendo-se o sentido e a correção, o ponto e vírgula em “Os dados indicam caminhos; são as pessoas que os percorrem” poderia ser substituído por", "opcoes": ["vírgula seguida de “porque”.", "vírgula seguida de “portanto”.", "vírgula seguida de “embora”.", "vírgula seguida de “logo”.", "vírgula seguida de “mas”."], "gabarito": 4, "explicacao": "Há oposição entre as orações: os dados apenas indicam, mas quem percorre são as pessoas. A relação é adversativa."}, {"materia": "port", "texto_base": null, "enunciado": "Assinale a alternativa em que a concordância verbal está de acordo com a norma-padrão.", "opcoes": ["Aluga-se salas para atendimento às vítimas de fraude.", "Fazia dois anos que os golpes se repetiam no bairro.", "Existe, nos autos, provas suficientes contra o grupo.", "Faltou, no inquérito, os documentos da instituição.", "Devem haver outras vítimas do mesmo golpe na cidade."], "gabarito": 1, "explicacao": "'Fazer' indicando tempo é impessoal (singular). 'Haver' = existir é impessoal e transmite a impessoalidade ao auxiliar ('Deve haver'). 'Faltaram os documentos', 'Alugam-se salas' (passiva sintética) e 'Existem provas' concordam com o sujeito plural."}, {"materia": "port", "texto_base": null, "enunciado": "Assinale a alternativa em que o emprego do acento indicativo de crase está correto.", "opcoes": ["O investigador referiu-se àquela transferência suspeita.", "A testemunha assistiu à uma audiência de instrução.", "Os valores serão bloqueados à partir de segunda-feira.", "O relatório foi entregue à Vossa Senhoria pela manhã.", "O agente ficou frente à frente com o principal suspeito."], "gabarito": 0, "explicacao": "'Referir-se a' + 'aquela' = 'àquela'. Não há crase antes de verbo ('a partir'), de pronome de tratamento ('a Vossa Senhoria'), em expressões com palavras repetidas ('frente a frente') nem antes de artigo indefinido ('a uma')."}, {"materia": "port", "texto_base": null, "enunciado": "Assinale a alternativa em que a regência verbal está de acordo com a norma-padrão.", "opcoes": ["Os policiais chegaram no local do crime ainda cedo.", "Prefiro mais investigar fraudes do que patrulhar ruas.", "Esqueci do prazo para concluir o relatório final.", "O agente aspirava ao cargo de chefia havia anos.", "O delegado assistiu o depoimento pela câmera da sala."], "gabarito": 3, "explicacao": "'Aspirar' no sentido de desejar exige 'a'. 'Assistir' (ver) também exige 'a' ('assistiu ao depoimento'). 'Preferir' rejeita 'mais' e 'do que' ('preferir A a B'). 'Chegar' pede 'a' ('chegaram ao local'). 'Esquecer' sem pronome não leva 'de' ('Esqueci o prazo')."}, {"materia": "rl", "texto_base": null, "enunciado": "Considere a proposição: “Se o suspeito estava no local e não tem álibi, então será indiciado”. A negação lógica dessa proposição é:", "opcoes": ["Se o suspeito não estava no local ou tem álibi, não será indiciado.", "Se o suspeito não será indiciado, então não estava no local.", "O suspeito estava no local, tem álibi e não será indiciado.", "O suspeito estava no local, não tem álibi e não será indiciado.", "O suspeito não estava no local ou tem álibi, e não será indiciado."], "gabarito": 3, "explicacao": "A negação de 'se P então Q' é 'P e não Q'. Aqui, P = 'estava no local e não tem álibi'. Logo: 'estava no local, não tem álibi e não será indiciado'."}, {"materia": "rl", "texto_base": null, "enunciado": "Uma proposição logicamente equivalente a “Se o candidato não é aprovado no curso de formação, então não é nomeado” é:", "opcoes": ["O candidato não é aprovado no curso de formação ou é nomeado.", "O candidato não é aprovado no curso de formação e não é nomeado.", "O candidato é aprovado no curso de formação e é nomeado.", "Se o candidato é aprovado no curso de formação, então é nomeado.", "Se o candidato é nomeado, então é aprovado no curso de formação."], "gabarito": 4, "explicacao": "A contrapositiva de '~A → ~N' é 'N → A': se é nomeado, então foi aprovado. A primeira alternativa errada é a inversa, que não é equivalente."}, {"materia": "rl", "texto_base": null, "enunciado": "Considere verdadeiras as premissas: “Todo investigador é servidor público”; “Nenhum servidor público é sócio-gerente de empresa”; “Alguns sócios-gerentes são advogados”. Conclui-se, necessariamente, que", "opcoes": ["alguns advogados são investigadores de polícia.", "todo advogado é sócio-gerente de empresa.", "alguns servidores públicos são advogados.", "nenhum investigador é sócio-gerente de empresa.", "nenhum advogado é servidor público efetivo."], "gabarito": 3, "explicacao": "Se todo investigador está no conjunto dos servidores e esse conjunto não toca o dos sócios-gerentes, nenhum investigador é sócio-gerente. Sobre os advogados nada se pode afirmar com certeza além de que alguns são sócios-gerentes."}, {"materia": "rl", "texto_base": null, "enunciado": "Uma equipe de 3 policiais será formada a partir de 5 investigadores e 4 escrivães. Se a equipe deve ter pelo menos um escrivão, o número de equipes diferentes é", "opcoes": ["70.", "74.", "84.", "60.", "64."], "gabarito": 1, "explicacao": "Total de equipes: C(9,3) = 84. Equipes sem escrivão (só investigadores): C(5,3) = 10. Logo, 84 − 10 = 74."}, {"materia": "rl", "texto_base": null, "enunciado": "Uma caixa tem 4 fichas de crimes patrimoniais e 6 de crimes contra a pessoa. Retiram-se 2 fichas ao acaso, sem reposição. A probabilidade de as duas serem do mesmo tipo é", "opcoes": ["7/15.", "2/5.", "13/25.", "1/3.", "8/15."], "gabarito": 0, "explicacao": "P = (4/10 × 3/9) + (6/10 × 5/9) = 12/90 + 30/90 = 42/90 = 7/15. O valor 13/25 seria a resposta com reposição."}, {"materia": "rl", "texto_base": null, "enunciado": "Ana, Beto, Caio e Duda trabalham, cada um, em um setor diferente: Homicídios, Roubos, Fraudes e Entorpecentes. Sabe-se que: Ana não trabalha em Homicídios nem em Fraudes; Beto não trabalha em Homicídios, Fraudes ou Entorpecentes; Caio não trabalha em Roubos, Fraudes ou Entorpecentes; Duda não trabalha em Entorpecentes. Então,", "opcoes": ["Caio trabalha no setor de Fraudes.", "Ana trabalha no setor de Roubos.", "Duda trabalha no setor de Roubos.", "Ana trabalha no setor de Entorpecentes.", "Beto trabalha no setor de Fraudes."], "gabarito": 3, "explicacao": "Caio só pode estar em Homicídios. Beto só pode estar em Roubos. Duda não está em Entorpecentes nem em Homicídios ou Roubos, então está em Fraudes. Sobra Entorpecentes para Ana."}, {"materia": "rl", "texto_base": null, "enunciado": "Em um mês, os registros de estelionato em uma cidade aumentaram 25%. No mês seguinte, diminuíram 20%. Em relação ao número inicial, os registros", "opcoes": ["voltaram exatamente ao mesmo valor.", "ficaram 2,5% acima do valor inicial.", "ficaram 5% abaixo do valor inicial.", "ficaram 5% acima do valor inicial.", "ficaram 45% abaixo do valor inicial."], "gabarito": 0, "explicacao": "1,25 × 0,80 = 1,00. O aumento de 25% seguido de queda de 20% leva de volta ao valor inicial."}, {"materia": "inf", "texto_base": null, "enunciado": "Em uma planilha do Excel (Microsoft 365), a célula A1 contém 150 e a célula B1 está vazia. Na célula C1, foi digitada a fórmula =SEERRO(A1/B1;\"sem dados\"). O resultado exibido em C1 será", "opcoes": ["#VALOR!", "sem dados", "150", "#DIV/0!", "0"], "gabarito": 1, "explicacao": "Dividir por célula vazia equivale a dividir por zero e gera #DIV/0!. Como a fórmula está dentro de SEERRO, o erro é substituído pelo texto indicado: 'sem dados'."}, {"materia": "inf", "texto_base": null, "enunciado": "Um investigador mantém no Excel uma tabela em A2:C200, com o nome do suspeito na coluna A, o CPF na coluna B e o número do inquérito na coluna C. A fórmula =PROCV(\"Carlos Lima\";A2:C200;3;FALSO) retorna", "opcoes": ["o valor da terceira linha da tabela, seja qual for o nome.", "o CPF da primeira linha em que aparece Carlos Lima.", "a quantidade de vezes que Carlos Lima aparece na lista.", "o número do inquérito da linha em que está Carlos Lima.", "o nome mais parecido com Carlos Lima, por aproximação."], "gabarito": 3, "explicacao": "PROCV procura o valor na primeira coluna do intervalo e devolve o conteúdo da coluna indicada (3ª = coluna C). O argumento FALSO exige correspondência exata."}, {"materia": "inf", "texto_base": null, "enunciado": "No Excel, a célula C1 contém a fórmula =A1*$B$1. Se essa célula for copiada e colada na célula D3, a fórmula em D3 será", "opcoes": ["=A1*$B$1", "=B3*$B$1", "=A3*$B$1", "=B3*$C$3", "=B1*$B$3"], "gabarito": 1, "explicacao": "Ao copiar de C1 para D3, a referência relativa anda 1 coluna e 2 linhas (A1 vira B3). A referência absoluta $B$1 não muda."}, {"materia": "inf", "texto_base": null, "enunciado": "Os computadores de uma delegacia tiveram os arquivos criptografados por um programa malicioso, que exibiu uma mensagem exigindo pagamento em criptomoeda para liberá-los. A medida que mais reduz o impacto desse tipo de ataque é", "opcoes": ["pagar o resgate rapidamente para garantir a liberação dos arquivos.", "desativar o firewall para que o antivírus trabalhe com mais rapidez.", "trocar a senha do e-mail institucional depois que o ataque acontecer.", "manter cópias de segurança periódicas em local desconectado da rede.", "compartilhar a pasta afetada com todos para que os colegas ajudem."], "gabarito": 3, "explicacao": "É um ransomware. A defesa mais eficaz é ter backup isolado (offline), que o ataque não alcança. Pagar o resgate não garante a devolução dos dados e financia o crime."}, {"materia": "inf", "texto_base": null, "enunciado": "Um órgão faz backup completo no domingo e backups incrementais de segunda a sexta-feira. Se o servidor falhar no sábado de manhã, para recuperar todos os dados será preciso restaurar", "opcoes": ["apenas o backup completo de domingo, que já contém todas as alterações.", "o backup completo de domingo e somente o incremental da sexta-feira.", "o backup completo de domingo e todos os incrementais da semana.", "os incrementais de segunda a sexta, sem o backup completo de domingo.", "apenas o backup incremental feito na sexta-feira, que é o mais recente."], "gabarito": 2, "explicacao": "Cada incremental guarda só o que mudou desde o backup anterior, de qualquer tipo. Por isso, é preciso o completo e todos os incrementais em sequência. Com backup diferencial, bastariam o completo e o último diferencial."}, {"materia": "inf", "texto_base": null, "enunciado": "No Windows 11, um agente copiou três trechos diferentes de um relatório e agora quer colar o primeiro deles, que já não é o último copiado. O recurso que permite isso, quando ativado, é acionado pelas teclas", "opcoes": ["Ctrl + Alt + V", "Ctrl + Shift + V", "Windows + Tab", "Windows + V", "Windows + C"], "gabarito": 3, "explicacao": "Windows + V abre o histórico da área de transferência, onde ficam os itens copiados recentemente."}, {"materia": "inf", "texto_base": null, "enunciado": "Um investigador precisa enviar o mesmo e-mail a vinte vítimas de um golpe, sem que uma veja o endereço das outras. Para isso, deve colocar os endereços no campo", "opcoes": ["Cc (com cópia).", "Para (destinatários).", "Responder a todos.", "Assunto da mensagem.", "Cco (cópia oculta)."], "gabarito": 4, "explicacao": "No campo Cco, cada destinatário recebe a mensagem sem ver quem mais a recebeu, o que preserva os dados das vítimas."}, {"materia": "Atualidades", "texto_base": null, "enunciado": "A 30ª Conferência das Nações Unidas sobre Mudanças Climáticas (COP30), realizada em novembro de 2025, teve como cidade-sede", "opcoes": ["Brasília, no DF.", "Rio de Janeiro, no RJ.", "Manaus, no Amazonas.", "Belém, no Pará.", "Salvador, na Bahia."], "gabarito": 3, "explicacao": "A COP30 foi realizada em Belém (PA), a primeira na Amazônia."}, {"materia": "Atualidades", "texto_base": null, "enunciado": "A reforma tributária do consumo, aprovada pela Emenda Constitucional 132/2023 e regulamentada em 2025, criou um modelo de IVA dual formado por", "opcoes": ["PIS, federal, e IPTU, de estados e municípios.", "CSLL, federal, e ITCMD, de estados e municípios.", "CBS, federal, e IBS, de estados e municípios.", "IPI, federal, e ICMS, de estados e municípios.", "ISS, federal, e IPVA, de estados e municípios."], "gabarito": 2, "explicacao": "A CBS (Contribuição sobre Bens e Serviços) substitui PIS e Cofins. O IBS (Imposto sobre Bens e Serviços) substitui ICMS e ISS. A transição começou em 2026 e vai até 2033."}, {"materia": "Atualidades", "texto_base": null, "enunciado": "Lei aprovada em 2025 alterou o Imposto de Renda da Pessoa Física a partir de 2026, prevendo", "opcoes": ["isenção para quem ganha até R$ 5 mil por mês.", "isenção para quem ganha até R$ 10 mil por mês.", "cobrança do imposto apenas sobre lucros de empresas.", "alíquota única de 15% para todos os salários.", "fim da declaração anual para os assalariados."], "gabarito": 0, "explicacao": "A mudança isenta do IR quem recebe até R$ 5 mil mensais, com redução parcial para faixas um pouco acima, compensada por tributação mínima sobre altas rendas."}, {"materia": "Atualidades", "texto_base": null, "enunciado": "Nas eleições gerais de 2026, a renovação do Senado Federal correspondeu a", "opcoes": ["todas as vagas: três senadores por estado.", "dois terços das vagas: dois senadores por estado.", "nenhuma vaga, pois o mandato foi prorrogado.", "metade das vagas: um ou dois por estado.", "um terço das vagas: um senador por estado."], "gabarito": 1, "explicacao": "O Senado se renova a cada 4 anos, alternadamente, por 1/3 e 2/3. Em 2018 foram 2/3, em 2022, 1/3, e em 2026, novamente 2/3."}, {"materia": "igual", "texto_base": null, "enunciado": "Durante uma discussão de trânsito, um motorista ofende o outro com termos referentes à cor da pele dele, atingindo sua honra. Após a Lei 14.532/2023, essa conduta configura", "opcoes": ["infração administrativa, sem repercussão na esfera penal.", "contravenção penal de preconceito, punida com multa.", "injúria racial, crime inafiançável e imprescritível.", "injúria simples, com ação penal privada do ofendido.", "difamação qualificada, que admite retratação do autor."], "gabarito": 2, "explicacao": "A Lei 14.532/2023 levou a injúria racial para a Lei 7.716/1989 (art. 2º-A), equiparando-a ao racismo: reclusão de 2 a 5 anos, ação pública incondicionada, inafiançável e imprescritível."}, {"materia": "igual", "texto_base": null, "enunciado": "Uma mulher procura a delegacia relatando agressões do ex-namorado, com quem manteve relacionamento por dois anos, mas com quem nunca morou. Nesse caso, a Lei Maria da Penha", "opcoes": ["aplica-se somente se a agressão tiver deixado lesões corporais graves.", "aplica-se, pois basta relação íntima de afeto, sem coabitação.", "aplica-se apenas se o casal tiver filhos em comum menores de idade.", "não se aplica, pois o relacionamento já terminou antes da agressão.", "não se aplica, pois exige que agressor e vítima tenham morado juntos."], "gabarito": 1, "explicacao": "Art. 5º, III, da Lei 11.340/2006: qualquer relação íntima de afeto, independentemente de coabitação. Súmula 600 do STJ."}, {"materia": "igual", "texto_base": null, "enunciado": "Um homem é preso em flagrante por descumprir medida protetiva de urgência imposta com base na Lei Maria da Penha. Quanto à fiança, é correto afirmar que", "opcoes": ["a autoridade policial deverá arbitrá-la imediatamente.", "o Ministério Público é quem arbitra o seu valor.", "o crime é inafiançável em qualquer circunstância.", "a vítima é quem decide se o preso pode ser solto.", "somente a autoridade judicial poderá concedê-la."], "gabarito": 4, "explicacao": "Art. 24-A, § 2º, da Lei 11.340/2006: na prisão em flagrante por descumprimento de medida protetiva, apenas o juiz pode conceder fiança."}, {"materia": "igual", "texto_base": null, "enunciado": "Um servidor público é condenado definitivamente por crime de tortura (Lei 9.455/1997). Quanto ao cargo, a condenação acarretará", "opcoes": ["a aposentadoria compulsória com proventos proporcionais.", "a suspensão do cargo pelo mesmo prazo da pena aplicada.", "a perda do cargo, desde que o juiz a motive na sentença.", "a perda do cargo e a interdição pelo dobro do prazo da pena.", "apenas uma advertência registrada nos assentos funcionais."], "gabarito": 3, "explicacao": "Art. 1º, § 5º, da Lei 9.455/1997: a condenação acarreta a perda do cargo, função ou emprego público e a interdição para seu exercício pelo dobro do prazo da pena aplicada. O efeito é automático."}, {"materia": "ml", "texto_base": null, "enunciado": "Uma mulher grávida foi agredida e, em consequência das lesões, sofreu aborto. Do ponto de vista médico-legal e penal, a lesão corporal classifica-se como", "opcoes": ["culposa.", "gravíssima.", "leve.", "grave.", "seguida de morte."], "gabarito": 1, "explicacao": "Art. 129, § 2º, V, do CP: lesão que resulta em aborto é gravíssima. Já a aceleração do parto é lesão grave (§ 1º, IV)."}, {"materia": "ml", "texto_base": null, "enunciado": "Em um local de crime, o perito constata que o cadáver apresenta rigidez apenas na mandíbula e na nuca, ainda sem rigidez nos membros. Isso sugere morte ocorrida há cerca de", "opcoes": ["12 a 24 horas.", "24 a 36 horas.", "15 a 20 dias.", "mais de 48 horas.", "1 a 3 horas."], "gabarito": 4, "explicacao": "A rigidez cadavérica começa pela mandíbula e pela nuca (lei de Nysten) entre 1 e 3 horas após a morte, generaliza-se em cerca de 8 horas e desaparece entre 36 e 48 horas."}, {"materia": "ml", "texto_base": null, "enunciado": "No exame de um cadáver, o perito encontra no pescoço um sulco oblíquo, ascendente, mais profundo no lado oposto ao nó e interrompido na região do nó. Esses achados são típicos de", "opcoes": ["estrangulamento.", "afogamento.", "esganadura.", "enforcamento.", "sufocação direta."], "gabarito": 3, "explicacao": "No enforcamento, o peso do corpo forma um sulco oblíquo, ascendente e interrompido no nó. No estrangulamento por laço, o sulco é horizontal e contínuo. Na esganadura, há marcas de unhas e dedos, sem sulco."}, {"materia": "ml", "texto_base": null, "enunciado": "Um ferimento de entrada de projétil de arma de fogo apresenta, ao redor, zona de tatuagem e zona de esfumaçamento. Esses sinais indicam disparo", "opcoes": ["a curta distância.", "a longa distância.", "por ricochete do projétil.", "após a morte da vítima.", "encostado no crânio."], "gabarito": 0, "explicacao": "Tatuagem (grãos de pólvora incrustados) e esfumaçamento (fuligem) são efeitos secundários do tiro e aparecem quando a boca do cano está próxima. No tiro a distância, eles não aparecem. No tiro encostado no crânio, forma-se a câmara de mina de Hoffmann."}, {"materia": "Legislação Geral", "texto_base": null, "enunciado": "Um órgão público precisa adquirir computadores com especificações usuais de mercado. Pela Lei 14.133/2021, a modalidade de licitação adequada é", "opcoes": ["o pregão.", "a concorrência.", "o leilão.", "o diálogo competitivo.", "o concurso."], "gabarito": 0, "explicacao": "Para bens e serviços comuns, é obrigatório o pregão (art. 6º, XLI, e art. 29), com critério de menor preço ou maior desconto."}, {"materia": "Legislação Geral", "texto_base": null, "enunciado": "Após um temporal destruir parte de um prédio público, a administração contrata uma obra por dispensa de licitação, com base em emergência. Pela Lei 14.133/2021, esse contrato", "opcoes": ["exige aprovação prévia do Tribunal de Contas.", "terá prazo de até 1 ano, vedada a prorrogação.", "poderá durar até 5 anos, prorrogáveis por mais 5.", "terá prazo de até 180 dias, prorrogável uma vez.", "poderá ser prorrogado enquanto durar a obra."], "gabarito": 1, "explicacao": "Art. 75, VIII: na emergência, o contrato é de no máximo 1 ano, vedadas a prorrogação e a recontratação da mesma empresa."}, {"materia": "Legislação Geral", "texto_base": null, "enunciado": "Um advogado sem procuração pede para examinar os autos de um inquérito policial já concluído e não sigiloso. Pelo Estatuto da Advocacia (Lei 8.906/1994), a autoridade", "opcoes": ["deve exigir a presença do investigado para liberar os autos.", "só pode permitir o acesso com autorização prévia do juiz.", "pode negar o acesso, pois o advogado não apresentou procuração.", "deve permitir apenas o exame, sendo proibida a cópia das peças.", "deve permitir o exame e a cópia de peças, mesmo sem procuração."], "gabarito": 4, "explicacao": "Art. 7º, XIV: é direito do advogado examinar, mesmo sem procuração, autos de flagrante e de investigações de qualquer natureza, podendo copiar peças. Se houver sigilo, exige-se procuração (§ 10)."}, {"materia": "Legislação Geral", "texto_base": null, "enunciado": "Pelo Estatuto da Advocacia, por motivo ligado ao exercício da profissão, o advogado somente pode ser preso em flagrante", "opcoes": ["em caso de qualquer crime doloso.", "com autorização prévia da OAB.", "em caso de contravenção penal.", "se o juiz expedir mandado antes.", "em caso de crime inafiançável."], "gabarito": 4, "explicacao": "Art. 7º, § 3º, da Lei 8.906/1994. Nesse caso, a prisão deve ter a presença de representante da OAB (art. 7º, IV)."}, {"materia": "pen", "texto_base": null, "enunciado": "Com intenção de matar, Júlio dispara contra Pedro, que cai ferido. Arrependido, Júlio o socorre e o leva ao hospital, onde Pedro sobrevive graças ao atendimento rápido. Júlio", "opcoes": ["responderá apenas pelas lesões corporais causadas.", "responderá por omissão de socorro em concurso material.", "ficará isento de pena, pois evitou o resultado morte.", "responderá por homicídio consumado, pois houve dolo.", "responderá por tentativa de homicídio, com pena reduzida."], "gabarito": 0, "explicacao": "É arrependimento eficaz (art. 15 do CP): o agente, após executar, impede o resultado. Ele responde só pelos atos já praticados, no caso, lesão corporal."}, {"materia": "pen", "texto_base": null, "enunciado": "Paulo foi atacado com uma faca e, em legítima defesa, desarmou e imobilizou o agressor. Já sem qualquer risco, continuou a golpeá-lo, causando lesões graves. Quanto aos golpes desferidos após a imobilização,", "opcoes": ["Paulo responde pelo excesso, pois cessou a agressão.", "Paulo está amparado pela legítima defesa em toda a ação.", "Paulo age em estado de necessidade, que exclui o crime.", "Paulo pratica fato atípico, pois a vítima o atacou antes.", "Paulo só responderia se tivesse causado a morte da vítima."], "gabarito": 0, "explicacao": "Art. 23, parágrafo único, do CP: o agente responde pelo excesso doloso ou culposo. Depois de cessada a agressão, a legítima defesa termina."}, {"materia": "pen", "texto_base": null, "enunciado": "Em uma loja com vigilância eletrônica e seguranças, Marta esconde roupas na bolsa e é abordada antes de sair. Segundo a jurisprudência do STJ, a existência desse sistema de vigilância", "opcoes": ["torna o crime impossível por ineficácia do meio.", "não torna impossível a configuração do furto.", "transforma o furto em mera contravenção penal.", "afasta a tentativa e torna o fato atípico.", "converte o furto em estelionato tentado."], "gabarito": 1, "explicacao": "Súmula 567 do STJ: o sistema de vigilância ou a presença de seguranças não tornam impossível a consumação do furto. Há furto tentado."}, {"materia": "pen", "texto_base": null, "enunciado": "Ari e Bia combinam furtar uma residência que acreditam estar vazia. Lá dentro, sem que Ari saiba ou aceite, Bia mata o vigia que os surpreendeu. Pela regra do Código Penal,", "opcoes": ["Ari responde por roubo simples, pois houve violência contra pessoa.", "Ari responde pelo furto, com pena aumentada se a morte era previsível.", "Ari fica isento de pena, pois não praticou a violência contra o vigia.", "Ari responde por homicídio culposo em concurso com o furto.", "Ari responde por latrocínio, pois aderiu à empreitada criminosa."], "gabarito": 1, "explicacao": "Art. 29, § 2º, do CP (cooperação dolosamente distinta): quem quis participar de crime menos grave responde por ele. A pena aumenta até a metade se o resultado mais grave era previsível."}, {"materia": "pen", "texto_base": null, "enunciado": "Usando uma arma de brinquedo, idêntica a uma verdadeira, Caio subtrai o celular de uma pessoa na rua. Considerando a legislação atual, Caio praticou", "opcoes": ["roubo simples, pois o simulacro só serve como grave ameaça.", "roubo majorado pelo emprego de arma de fogo, por ser idêntica.", "furto simples, pois a arma de brinquedo não causa nenhum perigo.", "roubo majorado pelo emprego de arma branca no momento do crime.", "extorsão, pois a vítima entregou o celular por medo do agente."], "gabarito": 0, "explicacao": "Desde a Lei 13.654/2018, a majorante exige arma de fogo (ou arma branca, conforme a Lei 13.964/2019). O simulacro configura a grave ameaça do roubo, sem aumento de pena."}, {"materia": "pen", "texto_base": null, "enunciado": "Fingindo ser comprador, Leo pede para fazer um test drive em um carro à venda e nunca mais volta com o veículo. Segundo o entendimento do STJ, Leo cometeu", "opcoes": ["furto mediante fraude, pois a fraude reduziu a vigilância.", "roubo impróprio, pois usou artifício para levar o veículo.", "estelionato, pois a vítima entregou o veículo de forma voluntária.", "apropriação indébita, pois já tinha a posse legítima do veículo.", "receptação, pois ficou com coisa que sabia ser de terceiro."], "gabarito": 0, "explicacao": "No test drive, o vendedor não transfere a posse de forma desvigiada: a fraude só serve para diminuir a vigilância e permitir a subtração. Por isso é furto qualificado pela fraude (art. 155, § 4º, II)."}, {"materia": "pen", "texto_base": null, "enunciado": "Rafael tinha 20 anos na data do crime e foi condenado aos 23. Quanto à prescrição,", "opcoes": ["os prazos são normais, pois era maior de 18 na data do fato.", "os prazos ficam suspensos até ele completar 21 anos de idade.", "os prazos são reduzidos pela metade, pela idade na data do fato.", "os prazos são reduzidos pela metade só se tiver mais de 70 anos.", "os prazos são aumentados em um terço, pela idade na condenação."], "gabarito": 2, "explicacao": "Art. 115 do CP: os prazos são reduzidos de metade quando o criminoso era menor de 21 anos na data do fato ou maior de 70 na data da sentença."}, {"materia": "pen", "texto_base": null, "enunciado": "Por negligência, um servidor deixa aberta a sala de bens apreendidos, e um terceiro subtrai objetos guardados ali. Antes da sentença irrecorrível, o servidor repara integralmente o dano. Nesse caso,", "opcoes": ["a reparação não tem efeito no peculato culposo.", "a pena do peculato culposo é reduzida de metade.", "o servidor responde por peculato-furto doloso.", "o servidor responde por prevaricação simples.", "extingue-se a punibilidade do peculato culposo."], "gabarito": 4, "explicacao": "Art. 312, § 3º, do CP: no peculato culposo, a reparação do dano antes da sentença irrecorrível extingue a punibilidade. Se for posterior, reduz de metade a pena imposta."}, {"materia": "pen", "texto_base": null, "enunciado": "Durante uma abordagem, um policial exige R$ 2.000,00 do motorista para não registrar o flagrante de um crime. O motorista paga. O policial cometeu", "opcoes": ["corrupção passiva, pois recebeu a vantagem indevida.", "corrupção ativa, pois a vantagem foi oferecida a ele.", "concussão, pois exigiu a vantagem em razão da função.", "prevaricação, pois deixou de praticar ato de ofício.", "extorsão, pois usou de grave ameaça contra a vítima."], "gabarito": 2, "explicacao": "Art. 316 do CP: concussão é exigir vantagem indevida em razão da função. Na corrupção passiva (art. 317), o funcionário solicita, recebe ou aceita promessa. 'Exigir' é concussão."}, {"materia": "pen", "texto_base": null, "enunciado": "Dois homens rendem uma motorista, mantêm-na no carro por algumas horas e a obrigam a sacar dinheiro em caixas eletrônicos. A restrição da liberdade era necessária para obter a vantagem. Trata-se de", "opcoes": ["extorsão mediante sequestro, crime hediondo autônomo.", "roubo simples em concurso com constrangimento ilegal.", "extorsão qualificada pela restrição da liberdade.", "sequestro e cárcere privado em concurso com furto.", "roubo majorado pela restrição da liberdade da vítima."], "gabarito": 2, "explicacao": "Art. 158, § 3º, do CP ('sequestro relâmpago'): extorsão cometida mediante restrição da liberdade da vítima, condição necessária para obter a vantagem."}, {"materia": "ppen", "texto_base": null, "enunciado": "Ao final de um inquérito, o delegado conclui que não há indícios suficientes de autoria. Nessa situação, o delegado", "opcoes": ["deve arquivar o inquérito e comunicar a decisão à vítima.", "pode arquivar o inquérito por despacho fundamentado próprio.", "deve arquivar, pois o MP só atua após a denúncia.", "pode arquivar, desde que ouça antes o investigado.", "não pode arquivar e deve remeter os autos com relatório."], "gabarito": 4, "explicacao": "Art. 17 do CPP: a autoridade policial não pode mandar arquivar autos de inquérito. Ela relata e remete; o arquivamento é feito pelo Ministério Público, com controle judicial."}, {"materia": "ppen", "texto_base": null, "enunciado": "Um suspeito é preso em flagrante por tráfico de drogas. Pela Lei 11.343/2006, o inquérito deverá ser concluído em", "opcoes": ["5 dias, por se tratar de crime hediondo.", "90 dias, podendo o prazo ser duplicado.", "15 dias, prorrogáveis por mais 15 dias.", "10 dias, improrrogáveis, como prevê o CPP.", "30 dias, prazo que o juiz pode duplicar."], "gabarito": 4, "explicacao": "Art. 51 da Lei de Drogas: 30 dias se o indiciado estiver preso e 90 se estiver solto, prazos que o juiz pode duplicar mediante pedido justificado."}, {"materia": "ppen", "texto_base": null, "enunciado": "Duas horas após um roubo, a polícia encontra um homem com a bolsa da vítima e a arma usada, o que faz presumir ser ele o autor. Essa é uma situação de flagrante", "opcoes": ["próprio, também chamado de real.", "presumido, também chamado de ficto.", "diferido, também chamado de ação controlada.", "impróprio, também chamado de quase flagrante.", "preparado, que torna o crime impossível."], "gabarito": 1, "explicacao": "Art. 302, IV, do CPP: é encontrado, logo depois, com instrumentos, armas ou objetos que façam presumir ser ele o autor. O impróprio (inciso III) exige perseguição logo após o crime."}, {"materia": "ppen", "texto_base": null, "enunciado": "Em perseguição a um suspeito em flagrante delito, às 23h, policiais entram, sem mandado e sem consentimento do morador, na casa onde ele se escondeu. Esse ingresso é", "opcoes": ["lícito, pois em flagrante se entra a qualquer hora.", "lícito apenas se houver ordem escrita do delegado.", "lícito apenas se o crime for hediondo ou equiparado.", "ilícito, pois à noite só se entra com mandado judicial.", "ilícito, pois exige consentimento do dono da casa."], "gabarito": 0, "explicacao": "Art. 5º, XI, da CF: em flagrante delito, desastre ou para prestar socorro, pode-se entrar na casa a qualquer hora, sem mandado. A ordem judicial é que só pode ser cumprida durante o dia."}, {"materia": "ppen", "texto_base": null, "enunciado": "Ao chegar a um local de crime, um policial percebe uma cápsula deflagrada no chão, de potencial interesse para a perícia. Pelas regras da cadeia de custódia, esse policial", "opcoes": ["deve lavar a cápsula para retirar sujeira e impressões.", "não tem responsabilidade, que é só do perito oficial.", "deve recolher a cápsula e entregá-la à vítima.", "deve preservar o vestígio até a chegada da perícia.", "deve aguardar a ordem do juiz para tocar no local."], "gabarito": 3, "explicacao": "Art. 158-A, § 2º, do CPP: o agente público que reconhecer um elemento como de potencial interesse para a prova pericial fica responsável por sua preservação."}, {"materia": "ppen", "texto_base": null, "enunciado": "Um suspeito apresenta à polícia um documento de identidade com rasura que impede a identificação. Pela Lei 12.037/2009, ele", "opcoes": ["pode ser identificado criminalmente mesmo assim.", "só pode ser identificado se for reincidente.", "deve ser solto e intimado a trazer outro documento.", "não pode ser identificado, pois apresentou documento.", "só pode ser identificado com autorização do MP."], "gabarito": 0, "explicacao": "Art. 3º, I, da Lei 12.037/2009: mesmo apresentando documento, cabe identificação criminal se ele tiver rasura ou indício de falsificação."}, {"materia": "ppen", "texto_base": null, "enunciado": "João, primário, é investigado por furto qualificado sem violência (pena de 2 a 8 anos) e confessa formal e circunstanciadamente. Quanto ao acordo de não persecução penal (ANPP),", "opcoes": ["não é cabível, pois a pena máxima supera 4 anos.", "não é cabível, pois só vale para crimes de menor potencial.", "é cabível, pois a pena mínima é inferior a 4 anos.", "não é cabível, pois o furto qualificado é hediondo.", "é cabível só se a vítima concordar expressamente."], "gabarito": 2, "explicacao": "Art. 28-A do CPP: cabe ANPP para infração sem violência ou grave ameaça, com pena mínima inferior a 4 anos, havendo confissão formal e circunstanciada."}, {"materia": "ppen", "texto_base": null, "enunciado": "Em uma investigação de roubo, o delegado entende necessária a prisão temporária do suspeito. Sobre essa prisão, é correto afirmar que", "opcoes": ["tem prazo de 30 dias para o crime de roubo.", "dispensa fundamentação na decisão judicial.", "não pode ser decretada de ofício pelo juiz.", "pode ser decretada durante a ação penal.", "pode ser decretada pelo próprio delegado."], "gabarito": 2, "explicacao": "Lei 7.960/1989: a temporária é decretada pelo juiz, só na investigação, mediante representação do delegado ou requerimento do MP. Para o roubo, o prazo é de 5 dias, prorrogável por mais 5."}, {"materia": "ppen", "texto_base": null, "enunciado": "Uma pessoa procura a delegacia para relatar que foi vítima de injúria simples, crime de ação penal privada. Nesse caso, o inquérito", "opcoes": ["só será instaurado a requisição do Ministério Público.", "será instaurado após autorização do juiz competente.", "deve ser instaurado de ofício pela autoridade policial.", "não pode ser instaurado em crimes de ação privada.", "só se instaura a requerimento de quem pode dar queixa."], "gabarito": 4, "explicacao": "Art. 5º, § 5º, do CPP: nos crimes de ação privada, a autoridade policial só instaura inquérito a requerimento de quem tenha qualidade para intentá-la."}, {"materia": "leg", "texto_base": null, "enunciado": "Durante uma abordagem, um homem é flagrado com pequena quantidade de cocaína destinada ao próprio consumo. Pela Lei 11.343/2006,", "opcoes": ["o fato é atípico, e a droga deve ser devolvida a ele após a perícia.", "ele responde por tráfico, pois portava droga ilícita em via pública.", "ele deve ser preso em flagrante e encaminhado ao sistema prisional.", "ele é autuado em flagrante, mas pode pagar fiança na própria delegacia.", "não se impõe prisão em flagrante, lavrando-se termo circunstanciado."], "gabarito": 4, "explicacao": "Art. 28 e art. 48, § 2º, da Lei de Drogas: para o porte para consumo pessoal não se impõe prisão em flagrante. O autor é encaminhado ao juízo ou assume o compromisso de comparecer, e lavra-se termo circunstanciado."}, {"materia": "leg", "texto_base": null, "enunciado": "Uma ré primária, de bons antecedentes, sem dedicação a atividades criminosas e sem integrar organização criminosa, é condenada por tráfico com a causa de diminuição do art. 33, § 4º. Esse tráfico privilegiado", "opcoes": ["impede qualquer substituição da pena de prisão.", "não é considerado crime hediondo ou equiparado.", "transforma o crime em porte para consumo próprio.", "só reduz a pena se a ré delatar os comparsas.", "é crime hediondo, com progressão mais rigorosa."], "gabarito": 1, "explicacao": "O STF afastou a hediondez do tráfico privilegiado, e a Lei 13.964/2019 incorporou isso à LEP (art. 112, § 5º). A redução vai de 1/6 a 2/3."}, {"materia": "leg", "texto_base": null, "enunciado": "Dono de uma loja, Ivo guarda no próprio estabelecimento um revólver de uso permitido, sem registro. Pelo Estatuto do Desarmamento, Ivo cometeu", "opcoes": ["porte ilegal de arma de fogo de uso restrito.", "comércio ilegal de arma de fogo de uso permitido.", "porte ilegal de arma de fogo de uso permitido.", "nenhum crime, pois a arma estava no seu comércio.", "posse irregular de arma de fogo de uso permitido."], "gabarito": 4, "explicacao": "Art. 12 da Lei 10.826/2003: manter arma em residência ou no local de trabalho, desde que seja o titular ou responsável pelo estabelecimento, é posse irregular. Fora disso, é porte (art. 14)."}, {"materia": "leg", "texto_base": null, "enunciado": "Em uma abordagem, um homem é encontrado com uma pistola de uso permitido, sem autorização, totalmente desmuniciada. Segundo a jurisprudência dos tribunais superiores,", "opcoes": ["há só infração administrativa, punida com multa.", "não há crime, pois a arma sem munição não oferece perigo.", "há crime apenas se houver munição ao alcance da mão.", "há crime, pois o porte ilegal é de perigo abstrato.", "não há crime se a arma tiver sido herdada pelo autor."], "gabarito": 3, "explicacao": "STF e STJ entendem que o porte de arma desmuniciada é crime, pois o tipo é de perigo abstrato. Só não há crime se a arma for comprovadamente inapta para disparar."}, {"materia": "leg", "texto_base": null, "enunciado": "Um delegado indicia um suspeito com base em interpretação razoável da lei, depois rejeitada pelo juiz, que adotou entendimento diferente. Pela Lei 13.869/2019, essa conduta", "opcoes": ["não configura abuso de autoridade, por divergência interpretativa.", "configura abuso de autoridade, pois o juiz discordou do delegado.", "configura crime de prevaricação, previsto no Código Penal.", "configura abuso de autoridade culposo, punido com detenção.", "configura abuso apenas se o suspeito ficou preso mais de um dia."], "gabarito": 0, "explicacao": "Art. 1º, § 2º, da Lei 13.869/2019: a divergência na interpretação da lei ou na avaliação de fatos e provas não configura abuso. Os crimes exigem dolo específico."}, {"materia": "leg", "texto_base": null, "enunciado": "Três pessoas se associam, com divisão de tarefas, para praticar furtos e estelionatos em série. Pela legislação vigente, elas cometem", "opcoes": ["organização criminosa, pois os crimes são praticados em série.", "concurso de pessoas, sem crime autônomo de associação.", "associação criminosa, pois são menos de quatro pessoas.", "organização criminosa, pois há divisão de tarefas entre elas.", "milícia privada, pois atuam de forma estável e permanente."], "gabarito": 2, "explicacao": "Organização criminosa exige 4 ou mais pessoas (Lei 12.850/2013, art. 1º, § 1º). Com 3 ou mais pessoas para cometer crimes, há associação criminosa (art. 288 do CP)."}, {"materia": "leg", "texto_base": null, "enunciado": "Sobre a colaboração premiada na Lei 12.850/2013, é correto afirmar que", "opcoes": ["o juiz não participa das negociações do acordo.", "o delegado pode celebrá-lo sem nenhuma manifestação do MP.", "a sentença pode se basear só na palavra do colaborador.", "o acordo só pode ser feito antes de iniciada a ação penal.", "o colaborador pode exercer o direito ao silêncio nos depoimentos."], "gabarito": 0, "explicacao": "Art. 4º, § 6º: o juiz não participa das negociações. A condenação não pode se basear apenas nas declarações do colaborador (§ 16), e ele renuncia ao direito ao silêncio nos depoimentos (§ 14)."}, {"materia": "leg", "texto_base": null, "enunciado": "Em uma investigação de ameaça (art. 147 do CP, punida com detenção), o delegado pensa em representar pela interceptação telefônica do suspeito. Pela Lei 9.296/1996, a medida", "opcoes": ["é cabível, desde que autorizada pelo próprio delegado.", "é cabível, por até 15 dias, renováveis sucessivamente.", "não é cabível, pois o crime prevê só detenção.", "não é cabível, pois só se admite em crimes hediondos.", "é cabível, pois a ameaça pode ser feita por telefone."], "gabarito": 2, "explicacao": "Art. 2º, III, da Lei 9.296/1996: não se admite interceptação quando o fato investigado for punido, no máximo, com detenção."}, {"materia": "leg", "texto_base": null, "enunciado": "Um homem é preso em flagrante por crime hediondo. Quanto à liberdade provisória, segundo a Lei 8.072/1990 e a jurisprudência do STF,", "opcoes": ["a liberdade provisória é proibida em qualquer caso concreto.", "o crime é inafiançável, mas cabe liberdade provisória sem fiança.", "o crime admite fiança, que deve ser arbitrada pelo delegado.", "o crime admite fiança, mas só se o preso for réu primário.", "a liberdade provisória depende de concordância da vítima."], "gabarito": 1, "explicacao": "Os hediondos são inafiançáveis (art. 2º, II), mas a vedação genérica à liberdade provisória foi retirada da lei, e o STF admite liberdade provisória sem fiança quando ausentes os requisitos da preventiva."}, {"materia": "cont", "texto_base": null, "enunciado": "Uma empresa comprou mercadorias para revenda por R$ 10.000,00, a prazo. Em relação ao patrimônio, esse fato contábil", "opcoes": ["não altera o ativo nem o passivo, sendo apenas um fato modificativo.", "aumenta o passivo e reduz o patrimônio líquido no mesmo valor.", "diminui o ativo e aumenta o passivo, reduzindo o patrimônio líquido.", "aumenta o ativo e o patrimônio líquido, sem alterar o passivo.", "aumenta o ativo e o passivo, sem alterar o patrimônio líquido."], "gabarito": 4, "explicacao": "Entra estoque (ativo) e surge a dívida com fornecedores (passivo), no mesmo valor. É fato permutativo: o patrimônio líquido não muda."}, {"materia": "cont", "texto_base": null, "enunciado": "Uma máquina foi adquirida por R$ 60.000,00, com valor residual estimado de R$ 6.000,00 e vida útil de 6 anos. Pelo método linear, o valor contábil da máquina após 2 anos de uso será de", "opcoes": ["R$ 44.000,00.", "R$ 40.000,00.", "R$ 48.000,00.", "R$ 42.000,00.", "R$ 36.000,00."], "gabarito": 3, "explicacao": "Depreciação anual = (60.000 − 6.000) ÷ 6 = 9.000. Em 2 anos: 18.000. Valor contábil = 60.000 − 18.000 = 42.000."}, {"materia": "cont", "texto_base": null, "enunciado": "Uma empresa apresenta ativo circulante de R$ 500.000,00, dos quais R$ 200.000,00 são estoques, e passivo circulante de R$ 250.000,00. O índice de liquidez seca é", "opcoes": ["1,5.", "2,8.", "0,8.", "2,0.", "1,2."], "gabarito": 4, "explicacao": "Liquidez seca = (AC − estoques) ÷ PC = (500.000 − 200.000) ÷ 250.000 = 1,2. A liquidez corrente seria 2,0."}, {"materia": "cont", "texto_base": null, "enunciado": "Uma loja tinha 10 unidades em estoque a R$ 5,00 cada e comprou mais 20 unidades a R$ 6,00 cada. Em seguida, vendeu 15 unidades. Pelo método PEPS, o custo das mercadorias vendidas foi de", "opcoes": ["R$ 75,00.", "R$ 85,00.", "R$ 80,00.", "R$ 70,00.", "R$ 90,00."], "gabarito": 2, "explicacao": "PEPS: saem primeiro as mais antigas. 10 × 5 + 5 × 6 = 50 + 30 = 80. Pela média ponderada seria 85 (custo médio de 5,67 × 15)."}, {"materia": "cont", "texto_base": null, "enunciado": "O aluguel do escritório referente a dezembro de 2025 foi pago somente em janeiro de 2026. Pelo regime de competência, essa despesa deve ser reconhecida em", "opcoes": ["janeiro de 2026, mês em que o pagamento foi feito.", "metade em dezembro de 2025 e metade em janeiro de 2026.", "dezembro de 2025, mês em que ocorreu o uso do imóvel.", "nenhum dos meses, pois é despesa de exercício anterior.", "dezembro de 2026, quando se fecha o exercício seguinte."], "gabarito": 2, "explicacao": "Pelo regime de competência, a despesa é reconhecida quando incorrida, independentemente do pagamento."}, {"materia": "cont", "texto_base": null, "enunciado": "Uma empresa teve receita bruta de vendas de R$ 100.000,00, impostos sobre vendas de R$ 15.000,00 e custo das mercadorias vendidas de R$ 45.000,00. O lucro bruto foi de", "opcoes": ["R$ 60.000,00.", "R$ 25.000,00.", "R$ 55.000,00.", "R$ 40.000,00.", "R$ 85.000,00."], "gabarito": 3, "explicacao": "Receita líquida = 100.000 − 15.000 = 85.000. Lucro bruto = 85.000 − 45.000 = 40.000."}, {"materia": "cont", "texto_base": null, "enunciado": "Uma empresa tem bens e direitos de R$ 150.000,00 e obrigações com terceiros de R$ 200.000,00. Sua situação patrimonial é de", "opcoes": ["patrimônio líquido positivo de R$ 50.000,00.", "passivo a descoberto de R$ 50.000,00.", "patrimônio líquido de R$ 350.000,00.", "patrimônio líquido nulo, sem dívidas.", "ativo a descoberto de R$ 50.000,00."], "gabarito": 1, "explicacao": "PL = Ativo − Passivo = 150.000 − 200.000 = −50.000. Quando as obrigações superam o ativo, há passivo a descoberto."}, {"materia": "cont", "texto_base": null, "enunciado": "Uma empresa pagou, em dinheiro, uma duplicata de R$ 10.000,00 devida a fornecedor, com juros de R$ 500,00 pelo atraso. O lançamento correto é", "opcoes": ["débito de Fornecedores (10.500) e crédito de Caixa (10.500).", "débito de Juros Passivos (10.500) e crédito de Fornecedores (10.500).", "débito de Caixa (10.000) e crédito de Juros Ativos (500) e Fornecedores.", "débito de Caixa (10.500) e crédito de Fornecedores e de Juros Passivos.", "débito de Fornecedores e de Juros Passivos e crédito de Caixa (10.500)."], "gabarito": 4, "explicacao": "Baixa-se a dívida (débito em Fornecedores, 10.000), reconhece-se a despesa (débito em Juros Passivos, 500) e sai o dinheiro (crédito em Caixa, 10.500). É fato misto diminutivo."}, {"materia": "const", "texto_base": null, "enunciado": "Um cidadão descobre que um órgão público mantém, em seu banco de dados, informação errada sobre ele e teve negado o pedido de correção. O instrumento constitucional adequado é o", "opcoes": ["mandado de injunção.", "mandado de segurança.", "habeas data.", "habeas corpus.", "ação popular."], "gabarito": 2, "explicacao": "Art. 5º, LXXII, da CF: o habeas data serve para conhecer e retificar informações pessoais em registros de entidades governamentais ou de caráter público."}, {"materia": "const", "texto_base": null, "enunciado": "Uma CPI estadual que investiga desvio de verbas aprova a interceptação das ligações telefônicas de um investigado. Essa medida é", "opcoes": ["válida, se o Ministério Público for ouvido antes.", "inválida, pois a interceptação exige ordem judicial.", "válida, pois a CPI tem poderes de autoridade judicial.", "válida, desde que aprovada por maioria absoluta.", "inválida, pois a CPI estadual não pode investigar."], "gabarito": 1, "explicacao": "A interceptação telefônica tem reserva de jurisdição (art. 5º, XII, da CF). A CPI pode quebrar sigilo de dados telefônicos (registros), mas não determinar interceptação."}, {"materia": "const", "texto_base": null, "enunciado": "Um policial militar, em serviço, comete crime militar contra um colega de farda. Pelo art. 144 da Constituição, a apuração desse crime", "opcoes": ["cabe à polícia penal, por se tratar de servidor do Estado.", "cabe à polícia civil, desde que haja requisição do MP.", "cabe à polícia federal, por envolver agente público.", "não cabe à polícia civil, que não apura infrações militares.", "cabe à polícia civil, que exerce a polícia judiciária."], "gabarito": 3, "explicacao": "Art. 144, § 4º: às polícias civis incumbem as funções de polícia judiciária e a apuração de infrações penais, exceto as militares (e as de competência da União)."}, {"materia": "const", "texto_base": null, "enunciado": "Com a Emenda Constitucional 104/2019, a segurança dos estabelecimentos penais passou a caber", "opcoes": ["às polícias penais federal, estaduais e distrital.", "às polícias militares, por sua atuação ostensiva.", "às polícias civis, como polícia judiciária.", "à Força Nacional, por convênio com os estados.", "às guardas municipais, por delegação dos estados."], "gabarito": 0, "explicacao": "Art. 144, VI e § 5º-A, da CF: as polícias penais, vinculadas ao órgão administrador do sistema penal, cuidam da segurança dos estabelecimentos penais."}, {"materia": "const", "texto_base": null, "enunciado": "Ao ser preso, um suspeito pergunta o nome dos policiais que o prenderam. Segundo a Constituição, esse pedido", "opcoes": ["pode ser negado, para proteger a segurança dos policiais.", "só deve ser atendido se houver ordem do juiz.", "pode ser negado, pois a prisão foi em flagrante.", "deve ser atendido, pois é direito constitucional do preso.", "só deve ser atendido após a audiência de custódia."], "gabarito": 3, "explicacao": "Art. 5º, LXIV: o preso tem direito à identificação dos responsáveis por sua prisão ou por seu interrogatório policial."}, {"materia": "const", "texto_base": null, "enunciado": "Um brasileiro naturalizado em 2020 é acusado no exterior de crime comum praticado em 2015. Quanto à extradição, ela", "opcoes": ["é impossível, pois ele já é brasileiro há anos.", "é possível, desde que ele concorde com a medida.", "é possível, mas apenas se o crime for hediondo.", "é possível, pois o crime é anterior à naturalização.", "é impossível, pois brasileiro nunca é extraditado."], "gabarito": 3, "explicacao": "Art. 5º, LI: o naturalizado pode ser extraditado por crime comum praticado antes da naturalização ou por envolvimento comprovado em tráfico de drogas, a qualquer tempo. O nato nunca é extraditado."}, {"materia": "const", "texto_base": null, "enunciado": "Um policial militar com 8 anos de serviço quer se candidatar a vereador. Pela Constituição, se ele for alistável,", "opcoes": ["é elegível e continua normalmente no serviço.", "é elegível, mas deve afastar-se da atividade.", "é elegível só se pedir transferência à reserva.", "é elegível, mas fica agregado pela autoridade.", "é inelegível, pois é militar da ativa."], "gabarito": 1, "explicacao": "Art. 14, § 8º: o militar com menos de 10 anos de serviço deve afastar-se da atividade. Com mais de 10 anos, é agregado e, se eleito, passa à inatividade."}, {"materia": "const", "texto_base": null, "enunciado": "O sindicato dos policiais civis de um estado aprova greve por reajuste salarial. Segundo o entendimento do STF,", "opcoes": ["a greve é vedada a policiais civis e a toda a segurança pública.", "a greve é permitida, desde que mantidos 30% do efetivo em serviço.", "a greve é permitida, pois o servidor civil tem direito de greve.", "a greve é permitida após decisão favorável da assembleia legislativa.", "a greve é vedada apenas aos delegados, mas não aos demais cargos."], "gabarito": 0, "explicacao": "No ARE 654.432 (Tema 541), o STF decidiu que o exercício do direito de greve é vedado aos policiais civis e a todos os servidores que atuam diretamente na segurança pública."}, {"materia": "adm", "texto_base": null, "enunciado": "O delegado-chefe aplica pena de suspensão a um investigador que faltou ao serviço sem justificativa. Ao fazer isso, a administração exerce o poder", "opcoes": ["discricionário puro.", "normativo.", "disciplinar.", "de polícia.", "regulamentar."], "gabarito": 2, "explicacao": "O poder disciplinar permite apurar infrações e aplicar penalidades aos servidores e às pessoas sujeitas à disciplina administrativa. O poder de polícia atua sobre particulares em geral."}, {"materia": "adm", "texto_base": null, "enunciado": "Diante de risco iminente de desabamento, a prefeitura interdita e demole um imóvel particular sem ordem judicial. Esse ato se apoia no atributo da", "opcoes": ["autoexecutoriedade.", "tipicidade.", "imperatividade.", "motivação.", "presunção de veracidade."], "gabarito": 0, "explicacao": "A autoexecutoriedade permite à administração executar suas decisões diretamente, sem recorrer ao Judiciário, quando a lei autoriza ou há urgência."}, {"materia": "adm", "texto_base": null, "enunciado": "Em 2026, a administração federal descobre que concedeu uma vantagem ilegal a um servidor de boa-fé em 2019. Pela Lei 9.784/1999, a anulação", "opcoes": ["não é possível, pois a vantagem foi concedida por lei.", "é possível, mas apenas por decisão do Poder Judiciário.", "não é mais possível, pois decaiu o prazo de 5 anos.", "é possível até 10 anos após a prática do ato.", "é possível a qualquer tempo, pois atos ilegais não geram direitos."], "gabarito": 2, "explicacao": "Art. 54 da Lei 9.784/1999: decai em 5 anos o direito da administração de anular atos favoráveis aos destinatários, salvo comprovada má-fé."}, {"materia": "adm", "texto_base": null, "enunciado": "Em perseguição, uma viatura policial atinge um pedestre que atravessava na faixa. Sobre a responsabilidade pelos danos,", "opcoes": ["o Estado não responde, pois o policial agia no estrito cumprimento do dever.", "a vítima deve processar diretamente o policial que dirigia a viatura.", "o Estado só responde se a vítima provar a culpa do policial motorista.", "o Estado e o policial respondem de forma objetiva e solidária perante a vítima.", "o Estado responde objetivamente e pode agir em regresso contra o policial culpado."], "gabarito": 4, "explicacao": "Art. 37, § 6º, da CF: responsabilidade objetiva do Estado, com ação regressiva contra o agente em caso de dolo ou culpa. O STF (Tema 940) entende que a vítima deve acionar o Estado, não o agente."}, {"materia": "adm", "texto_base": null, "enunciado": "Por descuido, um servidor deixa prescrever créditos do órgão, causando prejuízo, sem qualquer intenção de lesar. Após a Lei 14.230/2021, quanto à improbidade administrativa,", "opcoes": ["há ato de improbidade, mas só com pena de multa civil.", "há ato de improbidade, pois houve dano efetivo ao erário.", "não há improbidade, pois hoje a lei sempre exige dolo.", "há ato de improbidade culposo que causa lesão ao erário.", "há ato de improbidade que atenta contra os princípios."], "gabarito": 2, "explicacao": "A Lei 14.230/2021 acabou com a improbidade culposa: todas as modalidades exigem dolo. O servidor pode responder em outras esferas, como a disciplinar e a civil."}, {"materia": "adm", "texto_base": null, "enunciado": "Um policial é absolvido no processo penal por insuficiência de provas. Quanto ao processo administrativo disciplinar pelos mesmos fatos,", "opcoes": ["o processo deve ser arquivado, pois os fatos são os mesmos do processo penal.", "ele só pode receber advertência, por causa da absolvição no processo penal.", "ele pode ser punido, pois a absolvição não negou o fato nem a autoria.", "ele não pode ser punido, pois a absolvição penal vincula a administração.", "o processo fica suspenso até que surjam novas provas do crime investigado."], "gabarito": 2, "explicacao": "As esferas são independentes. A absolvição penal só afasta a responsabilidade administrativa quando nega a existência do fato ou a autoria (Lei 8.112/1990, art. 126)."}, {"materia": "adm", "texto_base": null, "enunciado": "O governador quer nomear um profissional sem vínculo com o serviço público para chefiar um setor. Quanto às formas de ocupação, é correto afirmar que", "opcoes": ["não pode ocupar nenhum dos dois, pois não fez concurso público.", "pode ser nomeado para função de confiança, mas não para cargo em comissão.", "pode ocupar ambos, desde que haja autorização da assembleia.", "pode ser nomeado para cargo em comissão, mas não para função de confiança.", "pode ocupar ambos, desde que tenha formação de nível superior."], "gabarito": 3, "explicacao": "Art. 37, V, da CF: funções de confiança são exclusivas de servidores efetivos. Cargos em comissão podem ser ocupados por pessoas de fora, respeitado o percentual mínimo reservado a servidores de carreira."}, {"materia": "adm", "texto_base": null, "enunciado": "A Polícia Civil cria, dentro de sua própria estrutura, uma nova delegacia especializada em crimes cibernéticos. Trata-se de", "opcoes": ["criação de autarquia, que depende de lei específica.", "descentralização por delegação a um particular.", "desconcentração, pois não surge nova pessoa jurídica.", "descentralização por outorga a nova entidade.", "concentração, pois reúne competências num só órgão."], "gabarito": 2, "explicacao": "Desconcentração é a distribuição de competências entre órgãos da mesma pessoa jurídica, com hierarquia. Na descentralização, a competência passa a outra pessoa."}, {"materia": "est", "texto_base": null, "enunciado": "As idades de 7 presos em uma operação foram: 18, 19, 19, 22, 25, 31 e 40 anos. A mediana e a moda dessas idades são, respectivamente,", "opcoes": ["24,9 e 19.", "22 e 19.", "19 e 22.", "22 e 25.", "25 e 19."], "gabarito": 1, "explicacao": "Ordenados os 7 valores, a mediana é o 4º: 22. A moda é o valor que mais se repete: 19. A média seria 174 ÷ 7 ≈ 24,9."}, {"materia": "est", "texto_base": null, "enunciado": "O número de ocorrências registradas em 8 plantões foi: 2, 4, 4, 4, 5, 5, 7 e 9. A variância populacional desses dados é", "opcoes": ["4.", "16.", "4,57.", "2.", "5."], "gabarito": 0, "explicacao": "Média = 40 ÷ 8 = 5. Soma dos quadrados dos desvios = 9 + 1 + 1 + 1 + 0 + 0 + 4 + 16 = 32. Variância populacional = 32 ÷ 8 = 4 (desvio-padrão 2). A amostral seria 32 ÷ 7 ≈ 4,57."}, {"materia": "est", "texto_base": null, "enunciado": "Se todos os valores de um conjunto de dados forem multiplicados por 3, a variância desse conjunto", "opcoes": ["aumenta em 3 unidades.", "fica multiplicada por 3.", "não se altera.", "fica dividida por 3.", "fica multiplicada por 9."], "gabarito": 4, "explicacao": "Multiplicar os dados por k multiplica o desvio-padrão por k e a variância por k². Com k = 3, a variância fica 9 vezes maior."}, {"materia": "est", "texto_base": null, "enunciado": "Na delegacia A, o tempo médio de atendimento é de 40 minutos, com desvio-padrão de 8. Na B, a média é de 100 minutos, com desvio-padrão de 15. Pelo coeficiente de variação,", "opcoes": ["a delegacia B é mais dispersa, pois tem desvio maior.", "a delegacia A é mais homogênea, com CV de 20%.", "a delegacia A é mais homogênea, com CV de 8%.", "a delegacia B é mais homogênea, com CV de 15%.", "as duas têm a mesma variabilidade relativa."], "gabarito": 3, "explicacao": "CV = desvio ÷ média. A: 8 ÷ 40 = 20%. B: 15 ÷ 100 = 15%. Menor CV indica menor dispersão relativa, ou seja, maior homogeneidade."}, {"materia": "est", "texto_base": null, "enunciado": "De 200 ocorrências, 120 foram roubos (72 à noite) e 80 foram furtos (20 à noite). Sorteando uma ocorrência registrada à noite, a probabilidade de ser roubo é", "opcoes": ["9/25.", "18/23.", "3/5.", "23/50.", "72/200."], "gabarito": 1, "explicacao": "À noite houve 72 + 20 = 92 ocorrências. P(roubo | noite) = 72 ÷ 92 = 18/23."}, {"materia": "est", "texto_base": null, "enunciado": "Três denúncias independentes chegam à delegacia, e cada uma tem probabilidade de 1/2 de ser procedente. A probabilidade de exatamente duas serem procedentes é", "opcoes": ["3/4.", "3/8.", "1/8.", "1/2.", "1/4."], "gabarito": 1, "explicacao": "Binomial: C(3,2) × (1/2)² × (1/2) = 3 × 1/8 = 3/8."}, {"materia": "est", "texto_base": null, "enunciado": "Em um conjunto de dados, o primeiro quartil é 20 e o terceiro quartil é 50. Pelo critério usual do diagrama de caixa (box plot), é considerado valor atípico superior todo valor acima de", "opcoes": ["75.", "80.", "65.", "110.", "95."], "gabarito": 4, "explicacao": "Amplitude interquartil = 50 − 20 = 30. Limite superior = Q3 + 1,5 × AIQ = 50 + 45 = 95."}, {"materia": "est", "texto_base": null, "enunciado": "O tempo de resposta a chamados segue distribuição normal com média de 100 segundos e desvio-padrão de 10 segundos. A porcentagem aproximada de chamados atendidos entre 90 e 110 segundos é", "opcoes": ["50%.", "99,7%.", "68%.", "34%.", "95%."], "gabarito": 2, "explicacao": "Na normal, cerca de 68% dos valores ficam a até 1 desvio-padrão da média (90 a 110). Cerca de 95% ficam a até 2 desvios e 99,7% a até 3."}]$q$::jsonb;
begin
  insert into public.simulados (trilha, data, titulo, estilo, duracao_min, publicado)
  values ('policial', date '2026-11-01', 'Simulado 2 · Policial', 'AOCP', 240, true)
  on conflict (trilha, data) do update set titulo = excluded.titulo, estilo = excluded.estilo, duracao_min = excluded.duracao_min
  returning id into sid;
  if exists (select 1 from public.simulado_respostas r where r.simulado_id = sid) then
    raise notice 'Simulado já iniciado por alguém: questões mantidas.';
  else
    delete from public.simulado_questoes where simulado_id = sid;
    insert into public.simulado_questoes (simulado_id, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao)
    select sid, e.n, e.v ->> 'materia', nullif(e.v ->> 'texto_base', ''), e.v ->> 'enunciado', e.v -> 'opcoes', (e.v ->> 'gabarito')::smallint, e.v ->> 'explicacao'
      from jsonb_array_elements(lista) with ordinality e(v, n);
    update public.simulados set publicado = true where id = sid;
  end if;
end $$;

select s.id, s.trilha, s.data - 1 as abre_sabado, s.data as fecha_domingo, s.titulo, s.estilo, s.duracao_min, s.publicado, count(q.ordem) as questoes
  from public.simulados s left join public.simulado_questoes q on q.simulado_id = s.id
 where s.trilha = 'policial' and s.data = date '2026-11-01' group by s.id;
